import{z as n,x as s,o as e,c as d,q as B,j as r,D as a,d as A,s as i,S as o,b as l}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"方言与口音","description":"","frontmatter":{"title":"方言与口音","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ml-dialect-accent.md","filePath":"llm/ml-dialect-accent.md","lastUpdated":1791413859000}'),m={name:"llm/ml-dialect-accent.md"};function D(p,E,c,C,h,F){const t=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=B('<h1 id="方言与口音" tabindex="-1">方言与口音 <a class="header-anchor" href="#方言与口音" aria-label="Permalink to &quot;方言与口音&quot;">​</a></h1><div class="epigraph"><p>「语言是有陆军海军的方言。」方言与口音不是语言的残次版本，而是被标准语的统计优势淹没的平行世界。</p><footer>—— Max Weinreich 语，经 Labov 转述；口音与识别差距据 Koenecke 等，PNAS 2020 整理</footer></div><p><a href="/llm/ml-multilingual-eval">上一课</a>把评测流水线落到作答语言与判卷语言上。但「一种语言」内部并不均匀：粤语与普通话共享书写系统却不同音；阿拉伯语的标准语与各方言的距离接近两门语言；同一种英语在不同口音下的识别率能差几倍。评测卷按标准变体采样，方言用户拿到的就是别人的分数。本课写变体谱系的工程处理：数据怎么采、模型怎么对、评测怎么分列。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准语言偏置由爬取造成：网页文本偏向官方书面语，方言活在口语、聊天与语音里，在语料配比中接近零。失败分三类。文本侧：模型把方言表达当错别字「纠正」，或改写成标准语，或干脆拒答——粤语书面语、拉美西语与半岛西语的用词差异、阿拉伯语方言口语全在此列。语音侧：自动语音识别的词错率按口音分层，标准口音好、边缘口音差。评测侧：按标准变体构造的基准测不出这些差异，平均分把边缘变体淹没——这正是<a href="/llm/ml-multilingual-eval">多语言评测</a>禁止单标量平均在语言内部的重演。</p><p><span class="marginnote">词错率（WER）翻译成大白话就是：识别结果要改多少个词才等于正确答案。算法是（替换数 + 多插入数 + 漏掉数）÷ 参考句词数。举例：参考句有 10 个词，机器认错 2 个、又多听出 1 个，词错率就是 3 ÷ 10 = 30%。所以「词错率翻倍」意味着用户说的话一半以上要靠猜。</span></p><h3 id="谱系-不是清单" tabindex="-1">谱系，不是清单 <a class="header-anchor" href="#谱系-不是清单" aria-label="Permalink to &quot;谱系，不是清单&quot;">​</a></h3><p>变体是连续谱：标准书面语 → 区域变体 → 口语变体 → 语音与口音层。工程上按谱系采样而不是按「语言清单」采样：每一层都要有数据、有评测子集、有覆盖声明。阿拉伯语有 MADAR 一类按城市编号方言的语料（Bouamor 等 2019），把方言当一等公民处理；中文的粤语、吴语、闽南语各有书面传统与社区语料，规模与规范度不同，不能被一个 <code>zh</code> 标签盖掉。</p><p><span class="marginnote">Koenecke 等 2020 测得：主流语音识别服务对黑人说话者的词错率约为白人说话者的两倍。口音差距不是学术细节，是同一产品对不同人群的服务质量分层。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据：按谱系分层采集。语音侧，Common Voice 一类众包语料的口音元数据是可用起点（Ardila 等 2020）；文本侧从社交媒体与本地社区文本补，过隐私审查。标签：变体标签进数据卡与评测分组，粒度跟随社区书写实践。模型：语音侧按口音分层评测驱动微调——<a href="/llm/whisper-large-v3">Whisper large-v3</a> 一类大规模弱监督模型显著压缩了口音差距但没有消除；文本侧用变体数据继续训练时，盯住标准语能力的回退，变体补充不能以牺牲标准语为代价。评测：每种变体分列分数与最坏值；人评必须招募该变体的母语者。</p><p><span class="marginnote">「变体补充不能牺牲标准语」这条是常见翻车点：模型不像人能随时切换语域，它只是在统计上模仿训练语料的混合比例。变体数据灌得太猛、标准语校验没跟上，常见结局是粤语用户体验上去了，普通话用户开始看到用词被悄悄「粤语化」。而「分列 + 最坏值」的意义就像逐个量体温：平均 37.2°C 的班级里可能有人正烧到 40°C，只有盯着最差那一列才找得到出问题的人群。</span></p>',12)),(e(),r(o,null,{default:a(()=>[i(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPEC%5B%22%E6%A0%87%E5%87%86%E4%B9%A6%E9%9D%A2%E8%AF%AD%22%5D%20--%3E%20REG%5B%22%E5%8C%BA%E5%9F%9F%E5%8F%98%E4%BD%93%22%5D%0A%20%20REG%20--%3E%20COL%5B%22%E5%8F%A3%E8%AF%AD%E5%8F%98%E4%BD%93%22%5D%0A%20%20COL%20--%3E%20SPK%5B%22%E8%AF%AD%E9%9F%B3%E4%B8%8E%E5%8F%A3%E9%9F%B3%E5%B1%82%22%5D%0A%20%20DATA%5B%22%E6%8C%89%E8%B0%B1%E7%B3%BB%E5%88%86%E5%B1%82%E9%87%87%E9%9B%86%E4%B8%8E%E6%89%93%E6%A0%87%22%5D%20--%3E%20EVAL%5B%22%E5%88%86%E5%B1%82%E8%AF%84%E6%B5%8B%EF%BC%9A%E5%88%86%E5%88%97%E5%8A%A0%E6%9C%80%E5%9D%8F%E5%80%BC%22%5D%0A%20%20SPK%20--%3E%20EVAL%0A%20%20EVAL%20--%3E%20DEC%5B%22%E8%A6%86%E7%9B%96%E5%A3%B0%E6%98%8E%E4%B8%8E%E5%B7%AE%E8%B7%9D%E6%8A%A5%E5%91%8A%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=l("h2",{id:"机制",tabindex:"-1"},[A("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=l("p",null,"分层评测之所以必要，是因为变体间的差距来源与语种间不同：不是「没学过这门语言」，而是「学过但信号稀」。这决定了补法的优先级——变体数据通常不需要从头改词表或动结构，缺的是继续训练数据与评测信号，成本远低于新增一门语言。但差距的分布有结构：语音侧的差距集中在语速、连读、声调与共享词表的切分上，文本侧集中在词汇与语法标记上。按谱系分层的评测能定位差距落在哪一层，从而决定补数据还是补转写规范；一刀切的「方言增强」会把预算花在差距最大但用户最少的那层。",-1)),(e(),r(o,null,{default:a(()=>[i(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOW%5B%22%E6%9F%90%E5%8F%98%E4%BD%93%E5%88%86%E6%95%B0%E5%81%8F%E4%BD%8E%22%5D%20--%3E%20Q1%7B%22%E5%B7%AE%E8%B7%9D%E5%9C%A8%E5%93%AA%E4%B8%80%E5%B1%82%EF%BC%9F%22%7D%0A%20%20Q1%20--%3E%7C%22%E8%AF%AD%E9%9F%B3%E5%B1%82%EF%BC%9A%E8%AF%AD%E9%80%9F%20%E8%BF%9E%E8%AF%BB%20%E5%A3%B0%E8%B0%83%22%7C%20A1%5B%22%E8%A1%A5%E5%8F%A3%E9%9F%B3%E8%AF%AD%E9%9F%B3%E6%95%B0%E6%8D%AE%E4%B8%8E%E8%BD%AC%E5%86%99%E8%A7%84%E8%8C%83%22%5D%0A%20%20Q1%20--%3E%7C%22%E6%96%87%E6%9C%AC%E5%B1%82%EF%BC%9A%E8%AF%8D%E6%B1%87%20%E8%AF%AD%E6%B3%95%E6%A0%87%E8%AE%B0%22%7C%20A2%5B%22%E8%A1%A5%E5%8F%98%E4%BD%93%E6%96%87%E6%9C%AC%E8%AF%AD%E6%96%99%E7%BB%A7%E7%BB%AD%E8%AE%AD%E7%BB%83%22%5D%0A%20%20Q1%20--%3E%7C%22%E6%B2%A1%E6%9C%89%E8%AF%A5%E5%8F%98%E4%BD%93%E5%AD%90%E9%9B%86%22%7C%20A3%5B%22%E5%85%88%E8%A1%A5%E8%AF%84%E6%B5%8B%E9%9B%86%E5%86%8D%E8%B0%88%E8%AE%AD%E7%BB%83%22%5D%0A%20%20A1%20--%3E%20CHK%5B%22%E6%A0%87%E5%87%86%E8%AF%AD%E5%9B%9E%E9%80%80%E6%A0%A1%E9%AA%8C%22%5D%0A%20%20A2%20--%3E%20CHK%0A%20%20A3%20--%3E%20RPT%5B%22%E5%86%99%E5%85%A5%E8%A6%86%E7%9B%96%E5%A3%B0%E6%98%8E%22%5D%0A%20%20CHK%20--%3E%20RPT%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=B('<p><span class="marginnote">这张图回答的问题是：「发现某方言分数差，第一步做什么？」答案不是直接开训，而是先定位差距落在哪一层。初学者容易以为「数据多多益善」，实际上没有评测子集时你连修没修好都量不出来——先补尺子，再补料。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>变体处理有三个容易走偏的方向。一是把方言当「带口音的标准语」硬转写：丢失词汇与语法差异，母语者不认账。二是按变体给用户分级服务：口音数据应该用来补训练，不是用来路由到更低质量的服务——那是把测量工具当成了歧视依据。三是发明标准：哪些变体算独立语言、哪种正字法算规范，是社区身份问题（粤语书面语标准化仍在进行中），工程跟随社区的书写实践，不越权裁定。语音侧还有成本边界：全变体采集不可能，优先级按用户分布与差距大小排，并且把没测的变体如实写进覆盖声明。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>标准语言偏置来自爬取；失败分文本「纠正」、语音识别词错率分层、评测平均淹没三类。</li><li>变体按谱系分层采样与评测，每层分列分数与最坏值，不做语言清单。</li><li>口音差距是真实的服务分层（曾有约两倍词错率差的报告）；弱监督大模型压缩但不消除。</li><li>变体数据用于补训练而非用户分级；语言与方言的地位跟随社区实践，工程不发明标准。</li><li>出处：Bouamor et al., MADAR, LREC 2019；Ardila et al., Common Voice, LREC 2020；Koenecke et al., PNAS 2020；Radford et al., Whisper, 2022。</li></ul>',5))])}const _=n(m,[["render",D]]);export{f as __pageData,_ as default};
